"""Document storage on local disk."""
import os

from vault.core.config import DOCS_DIR


def read_blob(name: str) -> str:
    base_dir = os.path.abspath(DOCS_DIR)
    path = os.path.abspath(os.path.join(base_dir, name))

    if not path.startswith(base_dir + os.sep) and path != base_dir:
        raise PermissionError(f"Access denied: {name}")

    if not os.path.isfile(path):
        raise FileNotFoundError(name)
    with open(path, "r", errors="ignore") as handle:
        return handle.read()

"""Report templates.""
