"""Archive listings.""
import subprocess
import os

from vault.core.config import ARCHIVE_DIR


def list_archive(name: str) -> list[str]:
    target_path = os.path.abspath(os.path.join(ARCHIVE_DIR, name))
    if not target_path.startswith(os.path.abspath(ARCHIVE_DIR)):
        raise PermissionError(name)

    try:
        # Use a list with shell=False to prevent command injection
        result = subprocess.run(["ls", target_path], shell=False, capture_output=True, text=True, timeout=5)
        if result.returncode != 0:
            raise FileNotFoundError(name)
        return sorted(line for line in result.stdout.splitlines() if line)
    except subprocess.TimeoutExpired:
        raise ValueError("Operation timed out")
    except Exception:
        raise FileNotFoundError(name)

"""Post-login redirects.""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(target: str) -> str:
    parts = urlparse(target)
    if parts.scheme == "" and parts.netloc == "" and target.startswith("/") and not target.startswith("//"):
        return target
    if parts.scheme == "https" and parts.hostname in ALLOWED_REDIRECT_HOSTS:
        return target
    return "/home"


def logout_target(target: str) -> str:
    parts = urlparse(target)
    if parts.scheme == "" and parts.netloc == "" and target.startswith("/") and not target.startswith("//"):
        return target
    if parts.scheme == "https" and parts.hostname in ALLOWED_REDIRECT_HOSTS:
        return target
    return "/home"

"""Post-login redirects."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(target: str) -> str:
    if not target:
        return "/home"

    parts = urlparse(target)
    # Ensure target is a relative path: no scheme, no netloc, starts with / and not //
    if parts.scheme == "" and parts.netloc == "" and target.startswith("/") and not target.startswith("//"):
        return target

    if parts.scheme == "https" and parts.hostname in ALLOWED_REDIRECT_HOSTS:
        return target

    return "/home"


