"""Greeting banners.""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent SSTI, we avoid using str.format() on untrusted templates.
    # Instead, we use a simple replacement for the specific allowed placeholder.
    # This ensures that even if the user provides '{user.__init__...}', 
    # it is treated as a literal string and not evaluated.
    placeholder = "{user}"
    if placeholder in template:
        return template.replace(placeholder, name)
    return template

"""Greeting banners."""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # We only allow formatting a specific key 'user' which is a dictionary.
    # This prevents attribute access (dot notation) on the object.
    user_data = {'name': User(name).name}
    try:
        # We use a custom dictionary-like object or just a dict to ensure 
        # that only top-level keys are accessible via .format()
        return template.format(user=user_data)
    except (KeyError, AttributeError, IndexError) as e:
        raise ValueError("Invalid template")

"""Greeting banners.""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


class SafeUser:
    def __init__(self, name: str):
        self.name = name
    def __getattr__(self, item):
        if item == 'name':
            return self.name
        raise AttributeError('Access denied')


def banner(template: str, name: str) -> str:
    # To prevent arbitrary attribute access via str.format, 
    # we provide a proxy object that only exposes 'name'.
    # However, str.format can still be used to access attributes if the object 
    # has them. A safer way is to use a custom formatter or restrict the template.
    # Given the requirement to keep behavior for legitimate input, 
    # we use a simple replacement or a restricted mapping.

    # We will use a dictionary-based approach for formatting to avoid object traversal.
    # The legitimate template is 'Hello {user.name}!' or similar.
    # Since the original code used {user.name}, we must support that specific pattern.

    # A robust way to prevent attribute traversal in str.format is to not use it on untrusted strings.
    # But we must support the legitimate 'user.name' syntax.

    # We'll replace the template's {user.name} with a safe placeholder or use a custom Formatter.
    import string

    class RestrictedFormatter(string.Formatter):
        def get_value(self, key, args, kwargs):
            if isinstance(key, str) and key == 'user.name':
                return name
            if isinstance(key, str) and key == 'user':
                # If they just use {user}, we return the name to be safe, 
                # but the original code used {user.name} implicitly via User(name).name
                # Wait, the original code was: template.format(user=User(name))
                # and the template was 'Hello {user.name}!'
                # The exploit was {user.__init__...}
                return User(name)
            return super().get_value(key, args, kwargs)

        def get_field(self, field_name, args, kwargs):
            if field_name == 'user.name':
                return name, {}
            return super().get_field(field_name, args, kwargs)

    # To strictly enforce the invariant: only 'user.name' is allowed.
    # We check if the template contains any forbidden patterns.
    forbidden = ['__', 'globals', 'getattr', 'dict', 'class', 'module', 'config']
    for word in forbidden:
        if word in template:
            raise ValueError("Invalid template")

    # The simplest way to satisfy the requirement while fixing the vulnerability
    # and maintaining legitimate 'Hello {user.name}!' functionality:
    # We use a simple string replacement for the specific allowed pattern.
    # This avoids the security risks of str.format entirely.

    # However, the original code used template.format(user=User(name)).
    # To keep the exact behavior for legitimate input 'Hello {user.name}!', 
    # we can use a regex or a controlled format.

    # Let's use a safer approach: replace '{user.name}' with the actual name.
    # and '{user}' with the name (to be safe) or just handle the specific case.

    # If we want to support the exact original behavior: 
    # template.format(user=User(name))
    # We must ensure 'user' cannot access anything but 'name'.

    class SafeUserProxy:
        def __init__(self, name):
            self._name = name
        @property
        def name(self):
            return self._name
        def __getattr__(self, item):
            raise AttributeError("Access denied")
        def __getitem__(self, item):
            raise TypeError("Access denied")

    # We use a custom formatter to prevent any attribute access other than .name
    class StrictFormatter(string.Formatter):
        def get_field(self, field_name, args, kwargs):
            if field_name == 'user.name':
                return SafeUserProxy(name).name, {}
            raise ValueError("Invalid field")

    try:
        return StrictFormatter().format(template)
    except (ValueError, KeyError, IndexError, AttributeError):
        # If the template doesn't match our strict rules, we check if it's the simple case
        # or if it's just a plain string.
        if "{user.name}" in template:
             return template.replace("{user.name}", name)
        # If the user used {user}, the original code would have failed if they didn't provide .name
        # but the original code provided User(name) which has a .name attribute.
        # Let's just use the most direct fix: replace the dangerous .format call.
        return template.replace("{user.name}", name).replace("{user}", name)

