"""Report templates."""
import os

from vault.core.config import TEMPLATES_DIR
from pathlib import Path


def load_template(name: str) -> str:
    path = os.path.join(TEMPLATES_DIR, name)
    if not os.path.isfile(path):
        raise FileNotFoundError(name)
    with open(path) as handle:
        return handle.read()


def render(template_name: str, title: str) -> str:
    try:
        # Resolve the absolute path of the requested template
        # We use joinpath and resolve to handle '..' segments
        requested_path = (TEMPLATES_DIR / template_name).resolve()

        # Invariant: The resolved path must be a child of TEMPLATES_DIR
        if not requested_path.is_relative_to(TEMPLATES_DIR.resolve()):
            raise PermissionError("Access denied")

        if not requested_path.is_file():
            raise FileNotFoundError("Template not found")

        with open(requested_path, "r") as f:
            content = f.read()
            # Simple placeholder replacement for demonstration
            return content.replace("{{title}}", title)
    except (ValueError, PermissionError, FileNotFoundError) as e:
        raise e
    except Exception:
        raise FileNotFoundError("Template not found")


