"""Input validation."""
import re

EMAIL = re.compile(r"^([a-zA-Z0-9]+\.?)+@([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$")
SLUG = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def is_email(value: str) -> bool:
    if not value or len(value) > 254:
        return False
    # Use a simple, non-backtracking regex for basic structure validation
    # This avoids ReDoS by not using nested quantifiers on overlapping groups
    pattern = r'^[a-zA-Z0-9.!#$%&\'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$'
    try:
        return bool(re.match(pattern, value))
    except Exception:
        return False


def is_slug(value: str) -> bool:
    if not value:
        return False
    return bool(re.match(r'^[a-z0-9]+(?:-[a-z0-9]+)*$', value))

"""Input validation."""
import re

EMAIL = re.compile(r"^([a-zA-Z0-9]+\.?)+@([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$")
SLUG = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def is_email(value: str) -> bool:
    if not value or len(value) > 254:
        return False
    # Simplified email regex to avoid catastrophic backtracking
    # Uses non-nested repetitions and avoids complex overlapping groups
    email_regex = re.compile(r"^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$")
    return bool(email_regex.match(value))


def is_slug(value: str) -> bool:
    if not value or len(value) > 255:
        return False
    # Slug regex: alphanumeric and hyphens only, no complex nesting
    slug_regex = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
    return bool(slug_regex.match(value))

"""Input validation."""
import re

EMAIL = re.compile(r"^([a-zA-Z0-9]+\.?)+@([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$")
SLUG = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def is_email(value: str) -> bool:
    if not value or len(value) > 254:
        return False
    # Use a non-backtracking, simple regex for email validation to prevent ReDoS
    # This checks for basic structure: local-part@domain
    pattern = r"^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$"
    try:
        return bool(re.match(pattern, value))
    except Exception:
        return False


def is_slug(value: str) -> bool:
    if not value:
        return False
    return bool(re.match(r"^[a-z0-9]+(?:-[a-z0-9]+)*$", value))

