"""Input validation."""
import re

EMAIL = re.compile(r"^[a-zA-Z0-9]+(?:\.[a-zA-Z0-9]+)*@[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*\.[a-zA-Z]{2,}$")
SLUG = re.compile(r"^([a-z0-9]+-?)+$")


def is_email(value: str) -> bool:
    # Simplified email check for demonstration
    return bool(re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', value))


def is_slug(value: str) -> bool:
    # Use a non-backtracking regex pattern for slugs
    # Slugs are typically alphanumeric and hyphens/underscores
    # We avoid nested quantifiers like (a+)+ to prevent ReDoS
    if not value:
        return False
    return bool(re.fullmatch(r'[a-z0-9\-_]+', value))

"""Operational helpers that call system tools."""
import subprocess


def echo_status(host: str) -> str:
    """
    Checks the status of a host.
    """
    try:
        # Use subprocess.run with a list of arguments to avoid shell injection.
        # The shell=False (default) ensures arguments are not interpreted by a shell.
        result = subprocess.run(
            ["echo", f"checking {host}"],
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError as e:
        return f"Error: {e.stderr.strip()}"
    except Exception as e:
        return f"Error: {str(e)}"

"""Link previews for documents."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_FETCH_HOSTS
from vault.core.net import http_get
import urllib.request
import urllib.parse
import socket
import ipaddress


def preview(url: str) -> str:
    validate_url(url)
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')[:1000]
    except Exception as e:
        return f"Error fetching preview: {str(e)}"


def read_asset(url: str) -> str:
    validate_url(url)
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        return f"Error reading asset: {str(e)}"


def validate_url(url: str):
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        raise ValueError("Invalid scheme")
    if not parsed.hostname:
        raise ValueError("Invalid hostname")

    try:
        # Resolve hostname to IP to prevent DNS rebinding/bypass
        ip_address_str = socket.gethostbyname(parsed.hostname)
        ip = ipaddress.ip_address(ip_address_str)

        if ip.is_loopback or ip.is_private or ip.is_link_local or ip.is_multicast or ip.is_unspecified:
            raise PermissionError("Access to internal network is forbidden")
    except socket.gaierror:
        raise ValueError("Could not resolve hostname")
    except ValueError as e:
        if "Access to internal network" in str(e):
            raise
        raise ValueError("Invalid IP address")

