"""Link previews for documents."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_FETCH_HOSTS
from vault.core.net import http_get
import urllib.request
import urllib.parse
import socket
import ipaddress


def preview(url: str) -> str:
    if not is_safe_url(url):
        raise ValueError("Forbidden URL")
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')[:1000]
    except Exception:
        return "Error fetching preview"


def read_asset(url: str) -> str:
    if not is_safe_url(url):
        raise ValueError("Forbidden URL")
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')
    except Exception:
        return "Error reading asset"


ALLOWED_DOMAINS = {"example.com", "api.example.com"}


def is_safe_url(url: str) -> bool:
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in {"http", "https"}:
        return False

    hostname = parsed.hostname
    if not hostname:
        return False

    # If it's a domain we explicitly trust, skip IP checks
    if hostname in ALLOWED_DOMAINS:
        return True

    try:
        # Resolve hostname to IP to prevent DNS rebinding/bypass
        ip_address_str = socket.gethostbyname(hostname)
        ip = ipaddress.ip_address(ip_address_str)

        # Check if IP is private, loopback, link-local, etc.
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved:
            return False
        return True
    except (socket.gaierror, ValueError):
        return False

"""Link previews for documents."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_FETCH_HOSTS
from vault.core.net import http_get
import urllib.request
import urllib.parse
import socket
import ipaddress


def preview(url: str) -> str:
    if not _is_safe_url(url):
        raise ValueError("Invalid or forbidden URL")
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')[:1000]
    except Exception as e:
        return f"Error fetching preview: {str(e)}"


def read_asset(url: str) -> str:
    if not _is_safe_url(url):
        raise ValueError("Invalid or forbidden URL")
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        raise FileNotFoundError(f"Could not read asset: {str(e)}")


def _is_safe_url(url: str) -> bool:
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in ('http', 'https'):
        return False
    if not parsed.hostname:
        return False

    try:
        # Resolve hostname to IP to prevent DNS rebinding and bypasses
        ip_address_str = socket.gethostbyname(parsed.hostname)
        ip = ipaddress.ip_address(ip_address_str)

        if ip.is_loopback:
            return False
        if ip.is_private:
            return False
        if ip.is_link_local:
            return False
        if ip.is_multicast:
            return False
        if ip.is_unspecified:
            return False
        # Check for specific metadata service ranges if not covered
        if ip_address_str == '169.254.169.254':
            return False

        return True
    except Exception:
        return False

