"""Post-login redirects."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(next_url: str) -> str:
    if not next_url:
        return "/home"

    parsed = urlparse(next_url)
    # If there is a scheme or a netloc, it's an absolute URL and potentially dangerous.
    # We only allow relative paths (where scheme and netloc are empty).
    if parsed.scheme or parsed.netloc:
        raise ValueError("Invalid redirect URL")

    # Ensure it starts with / to prevent protocol-relative URLs (e.g., //evil.com)
    if not next_url.startswith("/") or next_url.startswith("//"):
        raise ValueError("Invalid redirect URL")

    return next_url


def logout_target(next_url: str) -> str:
    return safe_next(next_url)

"""Post-login redirects."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(next_url: str) -> str:
    """
    Ensures the next_url is a relative path to prevent open redirect attacks.
    """
    if not next_url:
        return "/home"

    parsed = urlparse(next_url)
    # A safe relative URL should not have a scheme or a netloc (host)
    if parsed.scheme or parsed.netloc:
        raise ValueError("Invalid redirect URL")

    # Ensure it starts with a single slash to prevent protocol-relative URLs (e.g., //evil.com)
    if not next_url.startswith("/") or next_url.startswith("//"):
        raise ValueError("Invalid redirect URL")

    return next_url


def logout_target(next_url: str) -> str:
    return safe_next(next_url)

"""Post-login redirects."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(next_url: str) -> str:
    """
    Ensures the next_url is a relative path to prevent open redirect attacks.
    """
    if not next_url:
        return "/"

    parsed = urlparse(next_url)
    # A safe relative path should not have a scheme (http) or a netloc (domain)
    if parsed.scheme or parsed.netloc:
        raise ValueError("Invalid redirect URL")

    # Ensure it starts with a single slash and is not empty
    if not next_url.startswith("/") or next_url.startswith("//"):
        raise ValueError("Invalid redirect URL")

    return next_url


def logout_target(next_url: str) -> str:
    return safe_next(next_url)

"""Post-login redirects."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(next_url: str) -> str:
    if not next_url:
        return "/home"

    # Ensure the URL is relative and does not attempt to specify a scheme or authority
    # A safe relative URL starts with '/' but not '//'
    if next_url.startswith("//") or ":" in next_url.split("/", 1)[0]:
        return "/home"

    parsed = urlparse(next_url)
    if parsed.netloc or parsed.scheme:
        return "/home"

    return next_url


def logout_target(next_url: str) -> str:
    return safe_next(next_url)

