"""User preference blobs (base64-encoded pickles from the legacy client)."""
import base64
import pickle
import json


def load_prefs(blob: str) -> dict:
    try:
        # Use JSON instead of pickle to prevent RCE
        data = json.loads(blob)
        if not isinstance(data, dict):
            raise ValueError("Invalid format")
        return data
    except (json.JSONDecodeError, TypeError):
        raise ValueError("Invalid preference blob")

