"""Document storage on local disk."""
import os

from vault.core.config import DOCS_DIR


def read_blob(name: str) -> str:
    root = os.path.realpath(DOCS_DIR)
    path = os.path.realpath(os.path.join(root, name))
    if os.path.commonpath([root, path]) != root or not os.path.isfile(path):
        raise FileNotFoundError(name)
    with open(path, "r", errors="ignore") as handle:
        return handle.read()

"""Greeting banners."""
from vault.core import config
import string


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # Define allowed placeholders to prevent SSTI
    allowed_keys = {'name'}

    # Parse the template to ensure it only uses allowed keys
    # We use a custom Formatter to restrict access
    class SafeFormatter(string.Formatter):
        def get_value(self, key, args, kwargs):
            if isinstance(key, str) and key in allowed_keys:
                return kwargs[key]
            raise ValueError(f"Invalid template key: {key}")

        def check_unused_keys(self, format_string, parsed_argnums, parsed_field_names):
            # This is a basic implementation; in a real scenario,
            # we'd ensure no complex attribute access is attempted.
            pass

    formatter = SafeFormatter()
    try:
        # We validate that the template doesn't contain suspicious characters
        # that imply attribute access (like dots or brackets)
        # but the SafeFormatter logic is the primary defense.
        return formatter.format(template, name=name)
    except (KeyError, AttributeError, ValueError, IndexError) as e:
        raise ValueError("Invalid template format")

"""Greeting banners."""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent SSTI, we avoid using str.format() on user-provided templates.
    # Instead, we treat the template as a literal string and only perform simple replacement
    # of a specific placeholder, or we ensure no arbitrary attribute access can occur.
    # Here, we replace a specific placeholder '{name}' with the provided name.
    # This prevents the user from passing arbitrary format strings like '{user.__init__...}'
    # because we are not calling .format() on the template itself.
    return template.replace("{name}", name)

