from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent SSTI, we avoid using str.format() on user-provided templates.
    # We treat the template as a literal string and replace a specific placeholder.
    # This ensures that even if the user provides '{user.__init__...}', it is treated as text.
    placeholder = "{name}"
    if placeholder in template:
        return template.replace(placeholder, name)
    return f"{template} {name}"

"""Report templates."""
import os

from vault.core.config import TEMPLATES_DIR


def load_template(name: str) -> str:
    root = os.path.realpath(TEMPLATES_DIR)
    path = os.path.realpath(os.path.join(root, name))
    if os.path.commonpath([root, path]) != root:
        raise PermissionError("Access denied")
    if not os.path.isfile(path):
        raise FileNotFoundError(name)
    with open(path) as handle:
        return handle.read()


def render(name: str, title: str) -> str:
    return load_template(name).replace("{{title}}", title)

