import base64
import pickle
import io


def load_prefs(blob: str) -> dict:
    try:
        decoded = base64.b64decode(blob)
        # Use a safer loading mechanism. Since we want to support the legacy pickle
        # but prevent RCE, we use a restricted Unpickler.
        # Note: Standard pickle loads can still be dangerous, but restricting find_class
        # prevents the execution of arbitrary functions/classes.
        class SafeUnpickler(pickle.Unpickler):
            def find_class(self, module, name):
                # Only allow the most basic types if needed. 
                # For the provided legitimate blob, it uses 'theme' and 'lang' strings.
                # These are primitives and don't require find_class for custom types.
                if module == "builtins" and name in {"dict", "str", "int", "float", "bool"}:
                    return getattr(__import__("builtins"), name)
                raise pickle.UnpicklingError("Forbidden class")

        data = SafeUnpickler(io.BytesIO(decoded)).load()
    except Exception:
        raise ValueError("Invalid preference blob")

    if not isinstance(data, dict):
        return {"value": str(data)}
    return data


class RestrictedUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        # Only allow basic types and prevent RCE by blocking all modules
        # This is the only way to allow the 'legitimate' pickle while preventing execution
        raise pickle.UnpicklingError("Global access is forbidden")

    def load(self):
        # We allow standard builtins if necessary, but for a dict of prefs, 
        # we usually only need basic types which are handled by the parser itself
        # without needing find_class for custom objects.
        return super().load()

