"""Greeting banners.""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent SSTI, we avoid using str.format() on untrusted templates.
    # We use a simple replacement strategy for the allowed placeholder.
    # This ensures that only the literal string '{user}' is replaced.
    placeholder = "{user}"
    if placeholder not in template:
        return template

    # We only allow the specific placeholder '{user}' and prevent any attribute access
    # by not using the .format() engine which parses the string for attribute access.
    return template.replace(placeholder, name)

