"""Report templates.""
import os

from vault.core.config import TEMPLATES_DIR


def load_template(name: str) -> str:
    base_dir = os.path.abspath(TEMPLATES_DIR)
    path = os.path.abspath(os.path.join(base_dir, name))

    if not path.startswith(base_dir + os.sep) and path != base_dir:
        raise PermissionError(f"Access to {name} is denied")

    if not os.path.isfile(path):
        raise FileNotFoundError(name)
    with open(path) as handle:
        return handle.read()


def render(name: str, title: str) -> str:
    return load_template(name).replace("{{title}}", title)

