"""Post-login redirects."""
from urllib.parse import urlparse

from vault.core.config import ALLOWED_REDIRECT_HOSTS


def safe_next(next_url: str) -> str:
    if not next_url:
        return "/home"

    parsed = urlparse(next_url)

    # Ensure the URL is relative: no scheme and no netloc (host)
    # Also ensure it starts with / to prevent //evil.com attacks
    if not parsed.scheme and not parsed.netloc and next_url.startswith('/'):
        # Prevent //protocol-relative URLs
        if next_url.startswith('//'):
             raise ValueError("Invalid redirect URL")
        return next_url

    raise ValueError("Invalid redirect URL")


def logout_target(next_url: str) -> str:
    return safe_next(next_url)

