from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent format injection, we do not use str.format() on the user-provided template.
    # Instead, we treat the template as a literal and only replace a specific, safe placeholder.
    # This prevents access to __globals__, __init__, etc.
    return template.replace("{user}", User(name).name)

