"""Greeting banners.""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name
    def __str__(self) -> str:
        return self.name


def banner(template: str, name: str) -> str:
    # To prevent attribute traversal via format strings, we avoid passing the object itself.
    # Instead, we use a mapping that only contains the allowed key.
    return template.format(user_name=name)

"""Greeting banners.""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent template injection via str.format, we ensure the template
    # only contains the specific allowed placeholder '{user}' and no other
    # formatting syntax that could be used for attribute traversal.
    if "{user}" not in template:
        raise ValueError("Invalid template")

    # Check for any other curly braces that might indicate an injection attempt
    # or complex formatting expressions.
    # A simple way to enforce safety is to only allow the exact string '{user}'
    # and nothing else that looks like a format expression.
    import re
    if re.search(r"\{(?!user\})", template):
        raise ValueError("Invalid template syntax")

    return template.format(user=User(name))

"""Report templates.""
import os

from vault.core.config import TEMPLATES_DIR


def load_template(name: str) -> str:
    base_dir = os.path.abspath(TEMPLATES_DIR)
    path = os.path.abspath(os.path.join(base_dir, name))

    if not path.startswith(base_dir + os.sep) and path != base_dir:
        raise PermissionError(f"Access to {name} is denied")

    if not os.path.isfile(path):
        raise FileNotFoundError(name)
    with open(path) as handle:
        return handle.read()


def render(name: str, title: str) -> str:
    return load_template(name).replace("{{title}}", title)

