"""User preference blobs (base64-encoded pickles from the legacy client)."""
import base64
import pickle
import json


def load_prefs(blob: str) -> dict:
    """
    Loads preferences from a base64 encoded JSON string.
    Note: Switched from pickle to json to prevent arbitrary code execution.
    """
    try:
        data = json.loads(base64.b64decode(blob))
    except Exception as e:
        raise ValueError("Invalid preference blob") from e

    if not isinstance(data, dict):
        return {"value": str(data)}
    return data

