"""User preference blobs (base64-encoded pickles from the legacy client)."""
import base64
import pickle
import io


def load_prefs(blob: str) -> dict:
    try:
        decoded = base64.b64decode(blob)
    except Exception:
        raise ValueError("Invalid base64 encoding")

    # To prevent pickle RCE, we restrict the unpickler to only allow basic types.
    # We implement a custom Unpickler that overrides find_class to block all globals.
    class SafeUnpickler(pickle.Unpickler):
        def find_class(self, module, name):
            raise ValueError("Pickle reconstruction of arbitrary classes is forbidden")

    try:
        data = SafeUnpickler(io.BytesIO(decoded)).load()
    except Exception as e:
        raise ValueError(f"Failed to deserialize: {e}")

    if not isinstance(data, dict):
        return {"value": str(data)}
    return data

"""Archive listings.""
import subprocess
import os

from vault.core.config import ARCHIVE_DIR


def list_archive(name: str) -> list[str]:
    target_path = os.path.abspath(os.path.join(ARCHIVE_DIR, name))
    if not target_path.startswith(os.path.abspath(ARCHIVE_DIR)):
        raise PermissionError(name)

    try:
        result = subprocess.run(["ls", target_path], shell=False, capture_output=True, text=True, timeout=5)
        if result.returncode != 0:
            raise FileNotFoundError(name)
        return sorted(line for line in result.stdout.splitlines() if line)
    except subprocess.TimeoutExpired:
        raise ValueError("Operation timed out")

"""Archive listings.""
import subprocess
import os

from vault.core.config import ARCHIVE_DIR


def list_archive(name: str) -> list[str]:
    target_path = os.path.abspath(os.path.join(ARCHIVE_DIR, name))
    if not target_path.startswith(os.path.abspath(ARCHIVE_DIR)):
        raise PermissionError(name)

    if not os.path.isdir(target_path):
        raise FileNotFoundError(name)

    result = subprocess.run(["ls", target_path], shell=False, capture_output=True, text=True, timeout=5)
    if result.returncode != 0:
        raise FileNotFoundError(name)
    return sorted(line for line in result.stdout.splitlines() if line)

