"""Greeting banners."""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent SSTI, we avoid str.format() on a user-provided template.
    # Instead, we use a safer approach: replace the placeholder manually.
    # We only allow the literal string '{user}' to be replaced.
    placeholder = "{user}"
    if placeholder not in template:
        return template

    # We perform a simple replacement to ensure no attribute access via . or [] is possible.
    return template.replace(placeholder, name)

