import subprocess
import os

from vault.core.config import ARCHIVE_DIR


def list_archive(name: str) -> list[str]:
    target_path = os.path.abspath(os.path.join(ARCHIVE_DIR, name))
    if not target_path.startswith(os.path.abspath(ARCHIVE_DIR)):
        raise PermissionError(name)

