"""User preference blobs (base64-encoded pickles from the legacy client)."""
import base64
import pickle
import json


def load_prefs(blob: str) -> dict:
    """
    Loads preferences from a base64 encoded JSON string.
    Replaced pickle with json to prevent RCE.
    """
    try:
        data = json.loads(base64.b64decode(blob))
    except Exception:
        raise ValueError("Invalid preference blob")

    if not isinstance(data, dict):
        return {"value": str(data)}
    return data

"""Greeting banners.""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    # To prevent SSTI, we avoid using str.format() on user-provided templates.
    # Instead, we use a simple replacement strategy for the allowed placeholder.
    placeholder = "{user}"
    if placeholder not in template:
        return template

    # We only allow the specific placeholder '{user}' and do not allow attribute access.
    # This implementation replaces the exact string '{user}' with the name.
    return template.replace(placeholder, name)

