    safe_name = os.path.basename(name)
    result = subprocess.run([f"ls", os.path.join(ARCHIVE_DIR, safe_name)], capture_output=True, text=True, timeout=5)
    if result.returncode != 0:
        raise FileNotFoundError(f"Archive entry {name} not found")
    return sorted(line for line in result.stdout.splitlines() if line)

