"""User preference blobs (base64-encoded pickles from the legacy client)."""
import base64
import pickle
import io


def load_prefs(blob: str) -> dict:
    try:
        decoded_data = base64.b64decode(blob)
        # Use a restricted unpickler or validate the structure
        # Since we must avoid RCE, and pickle is inherently unsafe, 
        # we check if the result is a simple dict of primitives.
        data = pickle.loads(decoded_data)

        if not isinstance(data, dict):
            return {"value": str(data)}

        # Validate that all values in the dict are primitive types
        # to ensure no complex objects/functions were injected.
        allowed_types = (str, int, float, bool, type(None))
        for key, value in data.items():
            if not isinstance(key, str) or not isinstance(value, allowed_types):
                raise ValueError("Invalid preference format")

        return data
    except Exception:
        # If unpickling fails or validation fails, we treat it as a bad request
        raise ValueError("Invalid preference blob")

