 """Greeting banners."""
from vault.core import config


class User:
    def __init__(self, name: str):
        self.name = name


def banner(template: str, name: str) -> str:
    user = User(name)
    # Use a custom dictionary to restrict the attributes available to .format()
    # This ensures only 'user' key is available and its value is a safe proxy
    class SafeUser:
        def __init__(self, name):
            self.name = name

    # We use a small trick: since .format() looks up attributes, 
    # we provide a dictionary where the key is 'user' and the value is an object
    # that only has the name attribute. To prevent access to __globals__, etc.,
    # we ensure we aren't passing the actual User instance directly if it has risky attributes.
    # However, the standard .format() on a string with {user.name} will work 
    # if 'user' is an object with a 'name' attribute.

    # To strictly enforce the invariant that NO other attributes are accessible,
    # we can use a proxy object that only exposes 'name'.
    class NameOnlyProxy:
        def __init__(self, name):
            self._name = name
        @property
        def name(self):
            return self._name
        def __getattr__(self, name):
            raise AttributeError(f'Property {name} is not allowed')

    safe_user = NameOnlyProxy(name)
    return template.format(user=safe_user)

