"""User preference blobs (base64-encoded pickles from the legacy client)."""
import base64
import pickle


def load_prefs(blob: str) -> dict:
    def safe_load(data):
        if isinstance(data, dict):
            return {k: safe_load(v) for k, v in data.items()}
        if isinstance(data, (str, int, float, bool, type(None))):
            return data
        raise ValueError("Unsafe type detected in preferences")

