        binary_data = base64.b64decode(blob)
        data = SafeUnpickler(io.BytesIO(binary_data)).load()

        # Further validate the resulting object structure
        return safe_load(data) if isinstance(data, dict) else {"value": str(safe_load(data))}
    except Exception as e:
        if isinstance(e, ValueError):
            raise e
        raise ValueError("Invalid preference blob") from e

